\begin{lemma}[Poisson central expansion]\label{lem:poisson-central}
Let $f(u,\nu)$ be jointly analytic and bounded by one on a fixed polydisk.
There are $\nu_0,C>0$ such that, uniformly for $0\le\nu=k/h\le\nu_0$ and
$0\le K\le h/2$,
\begin{equation}
 \begin{split}
 \mathscr P_{h,k}f&=\sum_{j=0}^Kh^{-j}\mathscr T_j[f](\nu)
       +O\!\left(C^{K+1}(K+1)!h^{-K-1}\right),\\
 \mathscr T_0[f]&=f(\nu,\nu),\qquad
 \mathscr T_j[f]=\sum_{m=j+1}^{2j}
 t_{m,j}\nu^{m-j}\frac{\partial_u^mf(\nu,\nu)}{m!}\quad(j\ge1).
 \end{split}
 \label{eq:CG10}
\end{equation}
Moreover $\|\mathscr T_j[f]\|\le C^{j+1}j!$ on a smaller complex disk in
$\nu$, each $\mathscr T_j[f]$ with $j\ge1$ vanishes at $\nu=0$, and
$|\mathscr P_{h,k}f|\le C$.
\end{lemma}

