\begin{lemma}[Tight generating functions]\label{lem:tight-gf}
Let $(g,p)$ be stable and $0\le Y<y_0$. The tight generating function is
expressed through the shifted amplitudes by the exact identity
\begin{equation}
 \mathscr T_{g,p}(X(Y);\mathbf L)
 =\sum_{\mathbf d}U^Y_{g,p}(\mathbf d)
       \prod_{i=1}^p\frac{L_i^{2d_i}}{P^{d_i}(2d_i+1)!},
 \label{eq:tight-insertion}
\end{equation}
which fixes both the normalization and the meaning of the protected
boundaries. Its ratio to the ordinary marked generating function satisfies
\begin{equation}
 \begin{split}
 1\le\frac{\mathscr T_{g,p}(X(Y);\mathbf L)}{F_{g,p}(X(Y))}
   &\le\prod_{i=1}^p S(\varrho(Y)L_i),\\
 \frac{\mathscr T_{g,p}(X(Y);\mathbf L)}{F_{g,p}(X(Y))}
   &=\prod_{i=1}^p S(\varrho(Y)L_i)
        \bigl(1+O_{p,B}(g^{-1})\bigr)
       \quad\text{if }\max_i\varrho(Y)L_i\le B,
 \end{split}
 \label{eq:tight-real}
\end{equation}
where the inequality holds at every stable genus. Finally, for each fixed
physical length vector,
\begin{equation}
 \mathscr T_{g,p}(x;\mathbf L)=V(x)^{2g-2+p}R_{g,p,\mathbf L}(x),
 \qquad [x^j]R_{g,p,\mathbf L}(x)\ge0,
 \label{eq:tight-positive}
\end{equation}
and the series converge for $0\le x<x_c$.
\end{lemma}

